arguments.file_text:
@using sv_db2d525b4ba34ea49cd4e39ee9f14682.Models

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i + 1;
            var status = step == CurrentStep ? "active"
                       : CompletedSteps.Contains(step) ? "completed"
                       : "upcoming";
            var clickable = CompletedSteps.Contains(step) && step != CurrentStep;

            <li class="step-item @status"
                @onclick="() => { if (clickable) OnStepClicked.InvokeAsync(step); }"
                role="@(clickable ? "button" : "listitem")"
                tabindex="@(clickable ? 0 : -1)"
                aria-current="@(step == CurrentStep ? "step" : null)">
                <span class="step-circle">
                    @if (CompletedSteps.Contains(step) && step != CurrentStep)
                    {
                        <span class="checkmark">✓</span>
                    }
                    else
                    {
                        @step
                    }
                </span>
                <span class="step-label">@StepNames[i]</span>
            </li>

            @if (i < StepNames.Length - 1)
            {
                <li class="step-connector @(CompletedSteps.Contains(step) ? "completed" : "")" aria-hidden="true"></li>
            }
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter] public int CurrentStep { get; set; } = 1;
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}

.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    align-items: center;
    list-style: none;
    padding: 0;
    margin: 0;
    gap: 0;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.4rem;
    cursor: default;
    flex-shrink: 0;
}

.step-item.completed {
    cursor: pointer;
}

.step-circle {
    width: 2.2rem;
    height: 2.2rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    border: 2px solid #cbd5e1;
    background: #fff;
    color: #94a3b8;
    transition: all 0.2s;
}

.step-item.active .step-circle {
    border-color: #2563eb;
    background: #2563eb;
    color: #fff;
}

.step-item.completed .step-circle {
    border-color: #16a34a;
    background: #16a34a;
    color: #fff;
}

.step-label {
    font-size: 0.78rem;
    color: #94a3b8;
    text-align: center;
    white-space: nowrap;
}

.step-item.active .step-label {
    color: #2563eb;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #16a34a;
}

.step-connector {
    flex: 1;
    height: 2px;
