@using sv_db2d525b4ba34ea49cd4e39ee9f14682.Models

<fieldset class="reference-form">
    <legend>Reference @Index</legend>

    @if (ShowRemove)
    {
        <button type="button" class="btn-remove" @onclick="() => OnRemove.InvokeAsync()">✕ Remove</button>
    }

    <div class="form-row">
        <div class="form-group">
            <label>Name</label>
            <input type="text" @bind="Ref.Name" @bind:event="oninput" placeholder="Full name" />
        </div>
        <div class="form-group">
            <label>Relationship</label>
            <input type="text" @bind="Ref.Relationship" @bind:event="oninput" placeholder="e.g. Former Manager" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email</label>
            <input type="email" @bind="Ref.Email" @bind:event="oninput" placeholder="email@example.com" />
        </div>
        <div class="form-group">
            <label>Phone</label>
            <input type="tel" @bind="Ref.Phone" @bind:event="oninput" placeholder="(555) 123-4567" />
        </div>
    </div>
</fieldset>

@code {
    [Parameter, EditorRequired] public ReferenceModel Ref { get; set; } = default!;
    [Parameter] public int Index { get; set; } = 1;
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
}

