@using sv_db2d525b4ba34ea49cd4e39ee9f14682.Models

<div class="step-content">
    <h2>Personal Information</h2>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="validation-error" role="alert">@errorMessage</div>
    }

    <div class="form-group">
        <label>Full Name <span class="required">*</span></label>
        <input type="text" @bind="Model.FullName" @bind:event="oninput" placeholder="John Doe" />
    </div>

    <div class="form-group">
        <label>Email <span class="required">*</span></label>
        <input type="email" @bind="Model.Email" @bind:event="oninput" placeholder="john@example.com" />
        @if (isValidatingEmail)
        {
            <span class="validating">Validating email...</span>
        }
    </div>

    <div class="form-group">
        <label>Phone <span class="required">*</span></label>
        <input type="tel" @bind="Model.Phone" @bind:event="oninput" placeholder="(555) 123-4567" />
    </div>

    <div class="form-group">
        <label>Address <span class="required">*</span></label>
        <textarea @bind="Model.Address" @bind:event="oninput" rows="2" placeholder="123 Main St, City, State ZIP"></textarea>
    </div>

    <div class="step-buttons">
        <span></span>
        <button type="button" class="btn-primary" @onclick="HandleNext" disabled="@isValidatingEmail">Next →</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;

    private string? errorMessage;
    private bool isValidatingEmail;

    private async Task HandleNext()
    {
        errorMessage = null;

        if (string.IsNullOrWhiteSpace(Model.FullName))
        {
            errorMessage = "Full name is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Model.Email))
        {
            errorMessage = "Email is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Model.Phone))
        {
            errorMessage = "Phone is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Model.Address))
        {
            errorMessage = "Address is required.";
            return;
        }

        isValidatingEmail = true;
        try
        {
            var isValid = await ApplicationService.ValidateEmailAsync(Model.Email);
            if (!isValid)
            {
                errorMessage = "Please enter a valid email address.";
                return;
            }
        }
        finally
        {
            isValidatingEmail = false;
        }

        await OnNext.InvokeAsync();
    }
}

@using sv_db2d525b4ba34ea49cd4e39ee9f14682.Models

<div class="step-content">
    <h2>Work History</h2>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="validation-error" role="alert">@errorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="Entries[index]"
                       Index="index + 1"
                       ShowRemove="Entries.Count > 1"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    <div class="step-buttons">
        <button type="button" class="btn-outline" @onclick="OnBack">← Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next →</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? errorMessage;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        errorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                errorMessage = "Each position requires a company name and job title.";
                return;
            }
            if (entry.StartDate is null)
            {
                errorMessage = "Each position requires a start date.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

